SELECT RULE_ID AS "ruleId", RULE_NAME AS "ruleName", RULE_TYPE AS "ruleType", RULE_TYPE_NAME AS "ruleTypeName", CATEGORY_ID AS "categoryId", INVENTORY_ID AS "inventoryId", ALERT_CONDITION AS "alertCondition", UPPER_LIMIT AS "upperLimit", LOWER_LIMIT AS "lowerLimit", STAGNANT_DAYS AS "stagnantDays", ALERT_LEVEL AS "alertLevel", NOTIFY_METHOD AS "notifyMethod", NOTIFY_RECIPIENTS AS "notifyRecipients", CASE STATUS WHEN 0 THEN 'DISABLED' WHEN 1 THEN 'ENABLED' ELSE 'UNKNOWN' END AS "status", REMARK AS "remark", TO_CHAR(CREATE_TIME, 'YYYY-MM-DD HH24:MI:SS') AS "createTime", TO_CHAR(UPDATE_TIME, 'YYYY-MM-DD HH24:MI:SS') AS "updateTime" FROM TBL_INVENTORY_ALERT_RULE WHERE DELETED = 0
AND TENANT_ID = #{param.tenantId}
AND RULE_NAME LIKE '%' || #{param.ruleName} || '%'
AND RULE_TYPE = #{param.ruleType}
AND STATUS = CASE #{param.status} WHEN 'DISABLED' THEN 0 WHEN 'ENABLED' THEN 1 ELSE -1 END
AND ALERT_LEVEL = #{param.alertLevel}
ORDER BY CREATE_TIME DESC

SELECT * FROM TBL_INVENTORY_ALERT_RULE
WHERE RULE_TYPE = #{ruleType}
AND TENANT_ID = #{tenantId}
AND DELETED = 0
AND STATUS = 1
ORDER BY CREATE_TIME DESC

SELECT * FROM TBL_INVENTORY_ALERT_RULE
WHERE RULE_NAME = #{ruleName}
AND TENANT_ID = #{tenantId}
AND DELETED = 0
